private char[][] generate(int rows, int columns, Random random) {
    boolean[][] hWall = new boolean[rows + 1][columns];
    boolean[][] vWall = new boolean[rows][columns + 1];
    for (int r = 0; r <= rows; r++) Arrays.fill(hWall[r], true);
    for (int r = 0; r < rows; r++) Arrays.fill(vWall[r], true);

    boolean[][] visited = new boolean[rows][columns];
    Deque<int[]> stack = new ArrayDeque<>();
    stack.push(new int[]{0, 0});
    visited[0][0] = true;

    while (!stack.isEmpty()) {
        int[] current = stack.peek();
        int r = current[0], c = current[1];
        // collect unvisited neighbors
        List<int[]> neighbors = new ArrayList<>();
        for (int[] d : DIRECTIONS) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < columns && !visited[nr][nc]) {
                neighbors.add(new int[]{nr, nc});
            }
        }
        if (neighbors.isEmpty()) {
            stack.pop();
            continue;
        }
        int[] next = neighbors.get(random.nextInt(neighbors.size()));
        removeWall(r, c, next[0], next[1], hWall, vWall);
        visited[next[0]][next[1]] = true;
        stack.push(next);
    }
    ...
}
